#!/usr/bin/env python3
"""Regenerates the stable 1/100/1000 MCP tool catalog compile-time fixture."""

from pathlib import Path

count = 1000
output = Path(__file__).with_name("BenchmarkToolCatalog.g.cs")
lines = [
    "// Generated by generate_tool_catalog.py. Do not edit by hand.",
    "using System.Text.Json.Serialization;",
    "using Cntryl.Portia;",
    "",
    "namespace Cntryl.Portia;",
    "",
    "internal static class BenchmarkToolCatalog",
    "{",
    "    internal static PortiaBuilder Register(PortiaBuilder application, int catalogSize)",
    "    {",
    "        if (catalogSize is < 1 or > 1000)",
    "            throw new ArgumentOutOfRangeException(nameof(catalogSize));",
]

for index in range(count):
    name = f"BenchmarkTool{index:04d}"
    lines.extend(
        [
            f"        if (catalogSize >= {index + 1}) application.AddRequestHandler<BenchmarkToolHandler{index:04d}>()",
            f"            .AddMcpTool<{name}>();",
        ]
    )

lines.extend(["        return application;", "    }", "", "}", ""])

for index in range(count):
    name = f"BenchmarkTool{index:04d}"
    lines.extend(
        [
            f'[Discriminator("benchmark.tool.{index:04d}")]',
            f"sealed record {name} : BenchmarkToolRequest;",
        ]
    )

for index in range(count):
    request = f"BenchmarkTool{index:04d}"
    lines.extend(
        [
            f"sealed class BenchmarkToolHandler{index:04d}(BenchmarkState state) : IRequestHandler<{request}, BenchmarkOutput>",
            "{",
            f"    public ValueTask<Result<BenchmarkOutput>> HandleAsync(IRequestContext<{request}> context, CancellationToken cancellationToken) =>",
            "        BenchmarkToolHandlerCore.Handle(state, context.Request.ResultBytes, cancellationToken);",
            "}",
        ]
    )

lines.extend(
    [
        "[PortiaJsonContext]",
        '[JsonSerializable(typeof(BenchmarkRequest), TypeInfoPropertyName = "McpBenchmarkRequest")]',
        "[JsonSerializable(typeof(BenchmarkOutput))]",
        "[JsonSerializable(typeof(BenchmarkArguments))]",
        "[JsonSerializable(typeof(BenchmarkSource))]",
    ]
)
for index in range(count):
    lines.append(f"[JsonSerializable(typeof(BenchmarkTool{index:04d}))]")
lines.extend(["internal partial class McpBenchmarkJsonContext : JsonSerializerContext;", ""])

output.write_text("\n".join(lines), encoding="utf-8")
print(f"wrote {output}")
